    "merchant_desc": "Kráľovský trh. Môžeš tu nakupovať balíčky Vecí 1., 2. a 3. stupňa (zbrane, zbroj, šaty) a predávať nepotrebný majetok za výhodnejší kurz (1/2 za veci, 100 % za budovy).",
