    "castle_desc": "Pevný hrad. Prináša daňový výnos <strong>2 500 zl.</strong> a majiteľovi trvalo prepožičiava <strong>+1 Charizma</strong>. Vlastník: {owner}",
    "master_guild_desc": "Sídlo Majstra ({skill}). Ak hodíš <strong>4, 5 alebo 6</strong>, majster ťa prijme na výcvik na ďalšiu úroveň (1 000–5 000 zl.).",
    "market_desc": "Kráľovský trh. Môžeš tu nakupovať balíčky Vecí 1., 2. a 3. stupňa (zbrane, zbroj, šaty) a predávať nepotrebný majetok za výhodnejší kurz (1/2 za veci, 100 % za budovy).",
    "quest_field_desc": "Bojová úloha ({name}). Tu sa stretneš v súboji kockou so zverou, monštrom alebo drakom. Víťazstvo prináša zlato a zápis do kroniky.",
    "festival_field_desc": "Miesto konania Kráľovských Slávností (Turnaj, Ples, Dostihy). Tu získavaš najviac <strong>Sŕdc princeznej 💖</strong> na bodovú os!",
    "bonus_field_desc": "Kráľovská prémiová cesta. Hráč pri vstupe okamžite získava bonus <strong>+{gold}</strong>",
    "jester_field_desc": "Kaukliar ({name}). Každý vlastnený kaukliar zvyšuje nájomné, ktoré ti súperi platia pri vstupe na tvojich kaukliarov.",
    "chance_field_desc": "Pole osudu (Náhoda). Ťaháš náhodnú kartu s nečakanou udalosťou alebo kráľovským ediktom.",
    "dungeon_field_desc": "Kráľovský žalár. Zadržaní rytieri tu musia zložiť kauciu 1 000 zl., pokúsiť sa o útek (kocka 6), alebo si odsedieť trest.",
    "infirmary_field_desc": "Kráľovský lazaret (Špitál). Tu sa liečia rytieri po ťažkých súbojoch s monštrami a drakom a môžu si zakúpiť Hojivý elixír (+1 Boj, +0.5 💖 za 800 zl.).",
    "tavern_field_desc": "Hostinec U Zlatého korbeľa. Rytieri tu hrajú kocky s krčmárom o zlatky (stávka 500 zl.) alebo pozývajú spoločnosť na rundu pre zvýšenie slávy (+0.5 💖 za 400 zl.).",
    "town_enemy_desc": "Opevnené mesto patrí rytierovi {owner}. Prináša mýto a stále dane.",
