    "town_owned_desc": "Kráľovské mesto v tvojom držaní. Zaisťuje stále dane a prestíž na dvore.",
    "castle_owned_desc": "Tvoj mocný hrad. Koruna kráľovstva, pýcha rodu a zdroj úcty."
