    "step1_title": "Hod kockou",
    "step1_desc": "Hoď 1d6 pre štandardný pochod, zvoľ opatrný krok (1–4), alebo naskoč na koňa pre bleskový klus, cval či trysk.",
    "step2_title": "Pohyb & Rázcestie",
    "step2_desc": "Postupuj vpred. Ak dorazíš na rázcestie, figúrka sa zastaví a <strong>ty sám si zvolíš smer</strong> (vonkajšie dediny vs. vnútorný kráľovský chodník).",
    "step3_title": "Akcia na cieľovom poli",
    "step3_desc": "Kúp voľné panstvo / zaplať nájom sokovi / trénuj u Majstra / vstúp do arény drakov / zúčastni sa kráľovskej slávnosti!",
    "step4_title": "Koniec ťahu",
    "step4_desc": "Odovzdanie ťahu ďalšiemu rytierovi v poradí. Môžeš tiež aktivovať pergamen z brašny alebo skontrolovať stav svojho panstva.",
    "three_paths_title": "Tri rovnocenné cesty k víťazstvu",
    "path_warrior_title": "⚔️ Válečník & Lovec drakov",
    "path_warrior_desc": "Trénuje Boj, nakupuje zbrane a zbroj. Loví zver (U1), monštrá (U2) a poráža 2 drakov kráľovstva (U3) pre okamžitý triumf bez nutnosti zbierať srdcia!",
    "path_breeder_title": "🐎 Chovateľ & Veľkostatkár",
    "path_breeder_desc": "Skupuje zvieratá rovnakej sady (Kôň, Pes, Sokol) pre 80 % nájomné, buduje stajne s hospodárskym dobytkom a povyšuje dediny na nedobytné tvŕdze.",
    "path_courtier_title": "👑 Dvoran & Diplomat",
    "path_courtier_desc": "Trénuje Tanec a Charizmu, navštevuje zámocké plesy a slávnosti. Pri každej návšteve ŠTARTu získava kráľovskú audienciu a násobí všetky zisky sŕdc!",
    "step1_badge": "KROK 1",
    "step2_badge": "KROK 2",
    "step3_badge": "KROK 3",
    "step4_badge": "KROK 4",
    "path_warrior_header": "⚔️ 1. Cesta Bojovníka",
    "path_warrior_points": "• Investuj do cnosti <strong>Boj</strong>, kováčstiev a zbraní.<br/>• Plň úlohy netvorov U1–U2 a dominuj na <strong>Turnajoch</strong>.<br/>• <strong>Dračí triumf:</strong> Skolením 2 drakov okamžite vyhrávaš hru bez ohľadu na počet sŕdc!",
    "path_breeder_header": "🐎 2. Cesta Chovateľa",
    "path_breeder_points": "• Skupuj trojice zvierat (kôň + pes + sokol) pre bonus <strong>+1,5 💖</strong>.<br/>• Nakupuj hospodárske stáda v stajniach (ovce, ošípané, dobytok).<br/>• Drž 1. miesto v <strong>Chovateľskej prémii (+4,0 💖)</strong> a vyhrávaj Veľké dostihy.",
    "path_diplomat_header": "💃 3. Cesta Diplomata",
    "path_diplomat_points": "• Investuj do <strong>Tanca, Charizmy a plesových šiat</strong>.<br/>• Audiencie u kráľa na ŠTARTe a Hrade (<strong>+0,5 až +1,0 💖</strong>).<br/>• Drť súperov na <strong>Zámockých plesoch</strong> (až +5 💖 a 1 200 zl. za víťazstvo).",
    "tips_title": "💡 5 zlatých rád pre začínajúceho lorda",
    "tip1": "<strong>Zaobstaraj si koňa čo najskôr:</strong> Sprístupní ti 2 kocky pre pohyb, umožní rýchly cval a otvorí vstup do Veľkých dostihov.",
    "tip2": "<strong>Rázcestie je tvoja stratégia:</strong> Vonkajší okruh skrýva dediny a zvieratá; vnútorný kráľovský chodník ponúka majstrov cností, arény drakov a slávnosti.",
    "tip3": "<strong>Slávnosti sú kľúčom k srdciam:</strong> Sleduj podmienky účasti na Turnaji, Plese a Dostihov. 1. miesto dáva obrovský skok v srdciach!",
    "tip4": "<strong>Chráň sa pred zranením:</strong> V boji s monštrami používaj postoj <em>Opatrná obrana</em> za štítom, alebo si v lazarete kúp <em>Hojivý elixír</em> s ochranným amuletom.",
    "tip5": "<strong>Zbieraj pečate majstrov:</strong> Zisk 3 rôznych pečatí ti udelí <em>Rytiersku záštitu</em> – oslobodenie od vojnových daní a ošetrenie v lazarete zadarmo!",
