    "title": "Legenda o unesené princeznej a rubínovém náhrdelníku",
    "subtitle": "Od sokolieho posolstva a prísahy na dvore až po záchranu princeznej z dračej sluje — každé tvoje rozhodnutie na pláne píše pokračovanie tejto ságy.",
